function solve(input) {
  const { tree } = input;
  if (!tree || tree.length === 0 || tree[0] === null) return 0;
  function depth(idx) {
    if (idx >= tree.length || tree[idx] === null || tree[idx] === undefined) return 0;
    return 1 + Math.max(depth(2 * idx + 1), depth(2 * idx + 2));
  }
  return depth(0);
}
